// --- widget.h ---
#include <memory>

class Widget {
public:
    Widget();
    ~Widget(); // Destructor MUST be declared

    // Move operations must be declared due to custom dtor
    Widget(Widget&&) noexcept;
    Widget& operator=(Widget&&) noexcept;

    // Copy operations can be added if needed
    Widget(const Widget&);
    Widget& operator=(const Widget&);

private:
    struct Impl; // Forward-declared implementation type
    std::unique_ptr<Impl> pImpl; // The Pimpl pointer
};

// --- widget.cpp ---
#include "widget.h"
#include <string>

// Full definition of implementation type is now visible
struct Widget::Impl {
    std::string data;
    int value;
};

// Definitions of special members go in the .cpp file
Widget::Widget() : pImpl(std::make_unique<Impl>()) {}

Widget::~Widget() = default; // Definition is here, where Impl is complete

Widget::Widget(Widget&&) noexcept = default;
Widget& Widget::operator=(Widget&&) noexcept = default;

Widget::Widget(const Widget& other) 
    : pImpl(std::make_unique<Impl>(*other.pImpl)) {}

Widget& Widget::operator=(const Widget& other) {
    *pImpl = *other.pImpl;
    return *this;
}
